function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

function isGptFreeJob(job) {
  const mode = String(job?.accountMode || "").trim().toLowerCase();
  return mode === "gpt_free" || mode === "free" || mode === "chatgpt_free";
}

const BILLING_RETRY_LIMIT = 20;
const BILLING_IFRAME_TIMEOUT_MS = 8000;
const BILLING_RELOAD_DELAY_MS = 500;
const BILLING_FORM_STUCK_MS = 15000;

function isBillingUrl(url) {
  return url.includes("/checkout") || url.includes("/billing");
}

function isChatGptHomeUrl(url) {
  try {
    const u = new URL(url);
    return u.origin === "https://chatgpt.com" && u.pathname === "/" && !u.search && !u.hash;
  } catch (e) {
    return url === "https://chatgpt.com/" || url === "https://chatgpt.com";
  }
}

function cleanPanelText(text, fallback = "Đang xử lý...") {
  const raw = String(text || "");
  if (!raw.trim()) return fallback;
  if (!/[\u00c3\u00c2\u00e2\u0192\u20ac]/.test(raw)) return raw;
  const lowered = raw.toLowerCase();
  if (lowered.includes("checkout") || lowered.includes("billing")) return "Đang xử lý checkout.";
  if (lowered.includes("otp") || lowered.includes("code")) return "Đang lấy OTP.";
  if (lowered.includes("2fa") || lowered.includes("mfa") || lowered.includes("secret")) return "Đang xử lý 2FA.";
  if (lowered.includes("profile") || lowered.includes("full name")) return "Đang điền hồ sơ.";
  if (lowered.includes("password")) return "Đang điền mật khẩu.";
  if (lowered.includes("email") || lowered.includes("hotmail") || lowered.includes("gmail")) return "Đang xử lý email.";
  if (lowered.includes("popup") || lowered.includes("onboarding")) return "Đang xử lý popup.";
  if (lowered.includes("retry") || lowered.includes("reload") || lowered.includes("f5")) return "Đang thử lại.";
  if (lowered.includes("error") || lowered.includes("failed") || lowered.includes("loi")) return "Có lỗi trong quá trình tự động.";
  return fallback;
}

function findBillingErrorText() {
  const selectors = [
    '[data-testid="error-message"]',
    '.p-Notice--warning',
    '.p-FieldError',
    '[role="alert"]',
    '[aria-live="assertive"]',
    '[class*="error"]',
    '[class*="Error"]'
  ];
  const errorTexts = selectors
    .flatMap(selector => Array.from(document.querySelectorAll(selector)))
    .filter(isVisible)
    .map(el => (el.innerText || el.textContent || "").trim())
    .filter(Boolean);

  const body = document.body?.innerText || "";
  const bodyMatch = body.match(/(something went wrong|oops,? an error occurred|try again|unable to process|payment failed|declined|unsupported_country|deactivated|account_deactivated|account.*error|account.*disabled|cannot subscribe|thanh toƒÆ’†€™ƒ€š‚¡n thƒÆ’‚¡ƒ€š‚ºƒ€š‚¥t bƒÆ’‚¡ƒ€š‚ºƒ€š‚¡i|thƒÆ’‚¡ƒ€š‚ºƒ€š‚» cƒÆ’‚¡ƒ€š‚»ƒ€š‚§a bƒÆ’‚¡ƒ€š‚ºƒ€š‚¡n bƒÆ’‚¡ƒ€š‚»ƒ¢¢€š¬‚¹ tƒÆ’‚¡ƒ€š‚»ƒ€š‚« chƒÆ’‚¡ƒ€š‚»ƒ¢¢€š¬‹Å“i|lƒÆ’‚¡ƒ€š‚»ƒ¢¢€š¬¢‚¬i tƒÆ’†€™ƒ€š‚ i khoƒÆ’‚¡ƒ€š‚ºƒ€š‚£n)/i);
  if (bodyMatch) errorTexts.push(bodyMatch[0]);

  return errorTexts.find(text => /error|failed|declined|try again|went wrong|oops|deactivated|disabled|cannot subscribe|thƒÆ’‚¡ƒ€š‚ºƒ€š‚¥t bƒÆ’‚¡ƒ€š‚ºƒ€š‚¡i|tƒÆ’‚¡ƒ€š‚»ƒ€š‚« chƒÆ’‚¡ƒ€š‚»ƒ¢¢€š¬‹Å“i|lƒÆ’‚¡ƒ€š‚»ƒ¢¢€š¬¢‚¬i/i.test(text)) || "";
}

async function retryBillingAfterError(job, updateJob, log, errorText) {
  const retryCount = job.subRetry || 0;
  if (retryCount >= BILLING_RETRY_LIMIT) {
    log(`ƒÆ’‚¢ƒ€š‚ƒ€¦¢‚¬„¢ Retry billing ${retryCount} lƒÆ’‚¡ƒ€š‚ºƒ€š‚§n vƒÆ’‚¡ƒ€š‚ºƒ€š‚«n lƒÆ’‚¡ƒ€š‚»ƒ¢¢€š¬¢‚¬i. BƒÆ’†€™ƒ€š‚¡o fail...`);
    chrome.runtime.sendMessage({ type: "REPORT_ERROR", error: `Billing thƒÆ’‚¡ƒ€š‚ºƒ€š‚¥t bƒÆ’‚¡ƒ€š‚ºƒ€š‚¡i sau ${BILLING_RETRY_LIMIT} lƒÆ’‚¡ƒ€š‚ºƒ€š‚§n: ${errorText || "unknown"}` });
    return;
  }

  const nextRetry = retryCount + 1;
  log(`ƒÆ’‚¢ƒ€¦‚¡ƒ€š‚ ƒÆ’‚¯ƒ€š‚¸ƒ€š‚ Billing/account lƒÆ’‚¡ƒ€š‚»ƒ¢¢€š¬¢‚¬i lƒÆ’‚¡ƒ€š‚ºƒ€š‚§n ${nextRetry}/${BILLING_RETRY_LIMIT}. F5 rƒÆ’‚¡ƒ€š‚»ƒ¢¢€š¬…€œi ƒÆ’¢‚¬Å¾ƒ¢¢€š¬‹Å“iƒÆ’‚¡ƒ€š‚»ƒ€š‚n form lƒÆ’‚¡ƒ€š‚ºƒ€š‚¡i...`);
  await updateJob({
    billingFilled: false,
    billingStarted: false,
    billingStartedAt: 0,
    billingFillAttempts: 0,
    subscribeClicked: false,
    gopaySelected: false,
    subRetry: nextRetry
  });
  setTimeout(() => location.reload(), BILLING_RELOAD_DELAY_MS);
}

