function strongSubStorageGet(keys) {
  return new Promise((resolve) => chrome.storage.local.get(keys, resolve));
}

function strongSubStorageSet(payload) {
  return new Promise((resolve) => chrome.storage.local.set(payload, resolve));
}

function strongSubPickRandomItem(items) {
  if (!Array.isArray(items) || !items.length) return null;
  return items[Math.floor(Math.random() * items.length)] || null;
}

function strongSubRandomIntInclusive(min, max) {
  const lo = Math.ceil(min);
  const hi = Math.floor(max);
  return Math.floor(Math.random() * (hi - lo + 1)) + lo;
}

function strongSubRandomDigits(length) {
  let out = "";
  for (let i = 0; i < length; i += 1) out += String(strongSubRandomIntInclusive(0, 9));
  return out;
}

function strongSubRandomUpper(length) {
  let out = "";
  for (let i = 0; i < length; i += 1) out += String.fromCharCode(strongSubRandomIntInclusive(65, 90));
  return out;
}

function strongSubNormalizeAddressMode(mode) {
  return [
    STRONG_SUB_ADDRESS_MODE_RANDOM_KR,
    STRONG_SUB_ADDRESS_MODE_RANDOM_KR_INDO_MIX,
    STRONG_SUB_ADDRESS_MODE_RANDOM_US_INDO_MIX,
    STRONG_SUB_ADDRESS_MODE_RANDOM_UK_INDO_MIX,
    STRONG_SUB_ADDRESS_MODE_RANDOM_US,
    STRONG_SUB_ADDRESS_MODE_RANDOM_UK,
    STRONG_SUB_ADDRESS_MODE_RANDOM_JP,
    STRONG_SUB_ADDRESS_MODE_RANDOM_INDONESIA,
    STRONG_SUB_ADDRESS_MODE_RANDOM_INDIA,
    STRONG_SUB_ADDRESS_MODE_RANDOM_ALGERIA,
    STRONG_SUB_ADDRESS_MODE_RANDOM_KAZAKHSTAN,
    STRONG_SUB_ADDRESS_MODE_RANDOM_CHILE,
    STRONG_SUB_ADDRESS_MODE_RANDOM_ANY,
    STRONG_SUB_ADDRESS_MODE_FIXED_KR,
    STRONG_SUB_ADDRESS_MODE_FIXED_US,
    STRONG_SUB_ADDRESS_MODE_FIXED_UK,
    STRONG_SUB_ADDRESS_MODE_FIXED_JP,
    STRONG_SUB_ADDRESS_MODE_FIXED_INDONESIA,
    STRONG_SUB_ADDRESS_MODE_FIXED_INDIA,
    STRONG_SUB_ADDRESS_MODE_FIXED_ALGERIA,
    STRONG_SUB_ADDRESS_MODE_FIXED_KAZAKHSTAN,
    STRONG_SUB_ADDRESS_MODE_FIXED_CHILE
  ].includes(mode)
    ? mode
    : STRONG_SUB_ADDRESS_MODE_DEFAULT;
}

function strongSubAddressCountryKey(mode) {
  const normalized = strongSubNormalizeAddressMode(mode);
  if (normalized.includes("_us")) return "us";
  if (normalized.includes("_uk")) return "uk";
  if (normalized.includes("_jp")) return "jp";
  if (normalized.includes("_indonesia")) return "id";
  if (normalized.includes("_india")) return "in";
  if (normalized.includes("_algeria")) return "dz";
  if (normalized.includes("_kazakhstan")) return "kz";
  if (normalized.includes("_chile")) return "cl";
  return "kr";
}

function strongSubIsFixedAddressMode(mode) {
  return /^fixed_/.test(strongSubNormalizeAddressMode(mode));
}

function strongSubBuildIndoBottomPart() {
  const cityData = strongSubPickRandomItem([
    { city: "Jakarta", postalMin: 10000, postalMax: 15214, streets: ["Jl. Sudirman", "Jl. Thamrin", "Jl. Gatot Subroto"] },
    { city: "Surabaya", postalMin: 60000, postalMax: 60300, streets: ["Jl. Tunjungan", "Jl. Kertajaya", "Jl. Pemuda"] },
    { city: "Bandung", postalMin: 40000, postalMax: 46475, streets: ["Jl. Sudirman", "Jl. Ahmad Yani", "Jl. Diponegoro"] },
    { city: "Sidoarjo", postalMin: 61200, postalMax: 61299, streets: ["Jl. Pahlawan", "Jl. Diponegoro", "Jl. Raya"] }
  ]);
  return {
    city: cityData.city,
    address: `${strongSubPickRandomItem(cityData.streets)} No. ${strongSubRandomIntInclusive(1, 199)}`,
    postal: String(strongSubRandomIntInclusive(cityData.postalMin, cityData.postalMax)).padStart(5, "0")
  };
}

