          chrome.runtime.sendMessage({ type: "REPORT_ERROR", error: "GiƒÆ’†€™ƒ€š‚¡ khƒÆ’†€™ƒ€š‚´ng ƒÆ’¢‚¬Å¾ƒ¢¢€š¬‹Å“ƒÆ’†€™ƒ€š‚ºng (khƒÆ’†€™ƒ€š‚´ng cƒÆ’†€™ƒ€š‚³ promo 1 thƒÆ’†€™ƒ€š‚¡ng)" });
